#if UNITY_EDITOR
using System;using System.IO;using UnityEngine;using UnityEngine.AI;using UnityEditor;using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor{
[InitializeOnLoad] public static class PrisonEscapeWalkCheck{
static bool run,gateSeen;static int attempt;static float report;static int step,leg,corner,frame;static float wait,nextTap;static double limit;static NavMeshPath path;const string Log="Logs/Prison-escape-walk.txt";
static PrisonEscapeWalkCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("EscapeWalk",false)){SessionState.SetBool("EscapeWalk",false);run=true;step=0;limit=EditorApplication.timeSinceStartup+420;}};}
static void Tick(){if(!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&File.Exists("Temp/PrisonEscapeWalk")){File.Delete("Temp/PrisonEscapeWalk");File.WriteAllText(Log,"Continuous collision-based assisted walk with active searchlights and actual Mingi navigation; Tap API for ride. Prior missions seeded only.\n");SessionState.SetBool("EscapeWalk",true);EditorApplication.EnterPlaymode();return;}if(!run||!EditorApplication.isPlaying||frame==Time.frameCount)return;frame=Time.frameCount;try{var t=Object.FindFirstObjectByType<PrisonTransportEscape>();if(!t)return;var m=t.previous;if(EditorApplication.timeSinceStartup>limit)throw new Exception("Timeout step="+step+" leg="+leg+" player="+t.Player.transform.position+" friend="+t.Friend.transform.position);if(step==0){wait=Time.time+2;step=1;return;}if(Time.time<wait)return;
if(step==1){var o=m.previous.office;o.previous.previous.prison.introduction.DeveloperComplete();Object.FindFirstObjectByType<PrisonChickenMission>().DeveloperComplete();typeof(PrisonKeysMission).GetProperty("State").SetValue(o.previous,PrisonKeysMission.Stage.Complete);o.evidence.DeveloperComplete();o.Collect(PrisonOfficePoint.Kind.Uniforms);m.dialogue=Object.Instantiate(m.dialogue);m.dialogue.lineSeconds=.2f;t.dialogue=Object.Instantiate(t.dialogue);t.dialogue.lineSeconds=.3f;m.previous.DeveloperComplete();step=2;return;}
if(step==2){if(m.State!=PrisonNightMission.Stage.Sneak)return;File.AppendAllText(Log,"PASS evening handoff\n");step=3;leg=corner=0;path=null;}
if(step==3){if(m.Attempts!=attempt){attempt=m.Attempts;leg=corner=0;path=null;File.AppendAllText(Log,"Retry after exposure "+attempt+"\n");if(attempt>5)throw new Exception("Repeated exposure");}if(m.Complete){File.AppendAllText(Log,"PASS continuous walk to van; Mingi arrived\n");step=4;return;}if(m.State!=PrisonNightMission.Stage.Sneak)return;
var target=leg<m.route.Length?m.route[leg]:m.vehiclePoint;if(path==null){path=new NavMeshPath();NavMesh.SamplePosition(t.Player.transform.position,out var hit,3,NavMesh.AllAreas);if(!NavMesh.CalculatePath(hit.position,target.position,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete)throw new Exception("No path "+leg);corner=1;}
if(corner>=path.corners.Length){if(leg<m.route.Length){leg++;path=null;}return;}var delta=path.corners[corner]-t.Player.transform.position;delta.y=0;if(delta.magnitude<.35f){corner++;return;}
var next=t.Player.transform.position+delta.normalized*.7f;var cc=t.Player.GetComponent<CharacterController>();next.y=cc.bounds.min.y+.2f;
if(Time.time>report){report=Time.time+5;File.AppendAllText(Log,"Walk leg="+leg+" player="+t.Player.transform.position+" friend="+t.Friend.transform.position+"\n");}
bool lit=m.IsLit(new Vector3(t.Player.transform.position.x,cc.bounds.min.y+.8f,t.Player.transform.position.z),t.Player.transform);
if(!lit&&(m.IsLit(next,t.Player.transform)||m.IsLit(next+Vector3.up*.7f,t.Player.transform)||Vector3.Distance(t.Friend.transform.position,t.Player.transform.position)>7))return;
t.Player.transform.rotation=Quaternion.RotateTowards(t.Player.transform.rotation,Quaternion.LookRotation(delta),180*Time.deltaTime);cc.Move(delta.normalized*4f*Time.deltaTime);return;}
if(step==4){if(t.State!=PrisonTransportEscape.Stage.Ready)return;if(!t.Interact())return;File.AppendAllText(Log,"PASS board from arrival without teleport\n");step=5;}
if(step==5){if(t.State==PrisonTransportEscape.Stage.Riding&&Time.time>=nextTap){t.Tap();nextTap=Time.time+.25f;}if(t.State==PrisonTransportEscape.Stage.Gate&&!gateSeen){gateSeen=true;File.AppendAllText(Log,"PASS gate stop camera at "+t.vehicle.position+"\n");}if(gateSeen&&t.State==PrisonTransportEscape.Stage.Riding&&t.vehicle.position.z>55&&step==5){PrisonChickenCheck.Capture(t.film,"Logs/Prison-escape-through-gate.png");step=6;}}
if(step==6){if(t.State==PrisonTransportEscape.Stage.Riding&&Time.time>=nextTap){t.Tap();nextTap=Time.time+.25f;}}
if(t.Complete){if(!gateSeen||!t.Player.CanAct||!t.Friend.Following)throw new Exception("Final handoff failed");File.AppendAllText(Log,"PASS gate, extended ride, relief dialogue, controls and companion restored\nFINISHED");run=false;EditorApplication.ExitPlaymode();}
}catch(Exception e){File.AppendAllText(Log,e.ToString());run=false;EditorApplication.ExitPlaymode();}}
}}
#endif
